local __chained = {}
local function __take()
  for _, n in ipairs(__hook_names) do
    local f = _G[n]
    if f ~= nil then
      __chained[n] = __chained[n] or {}
      __chained[n][#__chained[n] + 1] = f
      _G[n] = nil
    end
  end
end

